test('invoiceTotals with discount and VAT together', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2, discountPercent: 15 },
      { sku: 'PRINT-A4', qty: 50 }, // 9% VAT
    ],
  }).value;

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // DES-HOUR: 2 * 8500 = 17000
  // Discount: 17000 * 15% = 2550
  // Amount after discount: 17000 - 2550 = 14450
  // VAT on DES-HOUR: 14450 * 21% = 3034.5 -> 3035 (rounded)
  // PRINT-A4: 50 * 37 = 1850
  // VAT on PRINT-A4: 1850 * 9% = 166.5 -> 167 (rounded)
  // Subtotal: 18850, Discount: 2550, VAT: 3202, Total: 19502
  assert.equal(r.value.subtotal, 18850);
  assert.equal(r.value.discount, 2550);
  assert.equal(r.value.vat, 3202);
  assert.equal(r.value.total, 19502);
});

