test('renderInvoiceText shows line discount inline', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  // Line should show: 2 × Design work (hour) @ €85.00 = €170.00 (10% off: -€17.00)
  assert.match(lines[2], /\(10% off: -€17\.00\)$/);
});

test('renderInvoiceText shows discount in totals section', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  // Should have: Subtotal, Discount, Total
  assert.match(lines[3], /^Subtotal: €170\.00/);
  assert.match(lines[4], /^Discount: -€17\.00/);
  assert.match(lines[5], /^Total: €153\.00/);
});

test('renderInvoiceText with multiple lines and mixed discounts', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 2, discountPercent: 20 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  // DES-HOUR: 2 * 8500 = 17000, discount 10% = 1700
  // DEV-HOUR: 2 * 9500 = 19000, discount 20% = 3800
  // Subtotal: 36000, Discount: 5500, Total: 30500
  assert.match(lines[2], /10% off: -€17\.00/);
  assert.match(lines[3], /20% off: -€38\.00/);
  assert.match(lines[4], /^Subtotal: €360\.00/);
  assert.match(lines[5], /^Discount: -€55\.00/);
  assert.match(lines[6], /^Total: €305\.00/);
});

test('renderInvoiceText without discount shows no discount line', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier, no tier discount
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  // Should not contain a "Discount:" line when there's no discount
  assert.match(lines[2], /^1 × Design work \(hour\)/);
  assert.equal(lines[3], 'Subtotal: €85.00');
  assert.equal(lines[4], 'Total: €85.00');
  assert.equal(lines.length, 5);
});

