  // Total: 8500 - 850 + 1607 = 9257
  assert.equal(r.value.subtotal, 8500);
  assert.equal(r.value.discount, 850);
  assert.equal(r.value.vat, 1607);
  assert.equal(r.value.total, 9257);
});

